import { readFileSync } from "node:fs";

const REPOS = ["fcp", "ai-agents", "infrastructure", "gitops", "byte", "claude-plugins", "rnd-kb", "rnd-kb-tooling", "fcp-local-lab"];
const FCP = ["cloud", "client", "sdk", "frontend", "common", "scripts", "pyproject.toml"];
const INFRA = ["modules", "terraform", "multi_tenant", "packer"];

const repoOf = (file) => {
  if (!file) return "no code: a decision";
  const note = file.match(/\((?:RhinoHealth\/)?([\w-]+)/)?.[1];
  if (REPOS.includes(note)) return note;
  const top = file.split(/[/ ]/)[0];
  if (REPOS.includes(top)) return top;
  if (FCP.includes(top)) return "fcp";
  if (INFRA.includes(top)) return "infrastructure";
  return "unknown: read the How";
};

const all = [0, 1, 2, 3, 4, 5, 6, 7, 8].flatMap((g) => JSON.parse(readFileSync(`g${g}.json`, "utf8")));
const count = {};
for (const t of all) {
  const repo = repoOf(t.code?.file);
  count[repo] = (count[repo] ?? 0) + 1;
}
for (const [repo, n] of Object.entries(count).sort((a, b) => b[1] - a[1])) console.log(String(n).padStart(4), repo);
